import {initPasswordVisibility} from './password-visibility.js?v=0.22.2';
import {mountReminders,mountBookingReminders} from './reminders-ui.js?v=0.21.0';
import {originBadge} from './origin-ui.js?v=0.20.0';
import {mountMarketing} from './marketing-ui.js?v=0.20.0';
import {fieldsPanel,fieldsFromForm,questionRow} from './form-fields-ui.js?v=0.17.1';
import {mountServiceImage} from './service-image-ui.js?v=0.16.1';
import {mountGoogleCalendar} from './calendar-choice.js?v=0.18.0';
import {mountPartnerAdmin} from './partners-admin.js?v=0.22.1';
import {mountCRM} from './crm-ui.js?v=0.20.0';
import {manualLeadForm,columnsForm,columnRow,intake,intakePanel,flowLabel,crmBoard,leadDetail as leadDetailContent,scheduleForm} from './lead-ui.js?v=0.20.0';
import {trialBanner,expiredTrialPage,subscriptionPage,trialsPage,conversionForm} from './trial-ui.js?v=0.22.0';
import {esc,money,dateLabel,icon,logo,serviceVisual,button,pill,fieldError,request,setCsrf,toast,modal,closeModal,submit,safeUrl} from './ui.js?v=0.16.1';
import {renderLogin} from './auth.js?v=0.22.2';
import {SECTORS} from './sectors.js?v=0.16.1';
import {TODAY,addDays,BRAND_FONTS,brandVariables} from './core.js?v=0.16.1';
initPasswordVisibility();



let user=null,tenants=[],workspace=null,contacts=[],mailSetup=null,pendingRequests=0,cronStatus=null,page='overview',calendarDay=TODAY();
let crmFocus=false,dragCard=null,movePending=false,boardReadGeneration=0;
const app=document.getElementById('app');
const agency=()=>user?.role==='superadmin';
const t=()=>workspace?.tenant;
const labels={marketing:'Marketing',overview:'Overzicht',calendar:'Agenda',bookings:'Afspraken',services:'Diensten',crm:'Aanvragen',customercrm:'CRM',widget:'Websitewidget',settings:'Beschikbaarheid',branding:'Huisstijl',emails:'Herinneringen',tenants:'Klanten beheren',contacts:'Aanvragen',trials:'Gratis trial gestart',partners:'Partners',subscription:'Mijn abonnement',security:'Mijn account'};
const header=(title,description,action='')=>`<div class="heading"><div><h1>${title}</h1><p class="sub">${description}</p></div>${action}</div>`;
const formButtons=(label='Opslaan')=>`${fieldError()}<div class="save-row">${button('Annuleren','close')}<button type="submit" class="btn primary">${label}</button></div>`;
const bookingStatus=b=>pill(b.status==='cancelled'?'Geannuleerd':'Bevestigd',b.status==='cancelled'?'grey':'');
const companyLeads=()=>workspace?.leads||[];
const crmAvailable=()=>t()?.settings.features.crm||intake(t()).mode==='request'||companyLeads().length>0;
const activeBookings=()=>workspace.bookings.filter(b=>b.status==='confirmed');

function updateBoardBadge(){const badge=document.querySelector('[data-page=crm] .nav-count');if(badge){const count=workspace?.board_unread||0;badge.textContent=String(count);badge.hidden=!count;badge.setAttribute('aria-label',count+' ongelezen aanvragen');}}
async function markBoardSeen(){
 const generation=++boardReadGeneration,current=workspace,id=t().id,linked=new Set(companyLeads().map(l=>l.bookingId));
 try{const result=await request('board/seen',{tenant:id,leads:companyLeads().map(l=>l.id),bookings:t().settings.features.crm?workspace.bookings.filter(b=>b.status==='confirmed'&&!linked.has(b.id)).map(b=>b.id):[]});if(workspace===current&&generation===boardReadGeneration){workspace.board_unread=result.unread||0;updateBoardBadge();}}
 catch(error){if(error.status===401)expired();else toast('De leesstatus kon niet worden opgeslagen. Probeer Aanvragen opnieuw te openen.');}
}
async function loadAgency(){const data=await request('tenants');tenants=data.tenants;mailSetup=data.mail;pendingRequests=data.notifications?.new_requests||0;cronStatus=data.cron;}
async function pollNotifications(){
 if(!user||document.hidden)return;
 if(workspace){const current=workspace,generation=boardReadGeneration,id=t().id;try{const data=await request('board/notifications',undefined,{tenant:id});if(workspace===current&&generation===boardReadGeneration){workspace.board_unread=data.unread||0;updateBoardBadge();}}catch(error){if(error.status===401)expired();}}
 if(!agency())return;
 try{const data=await request('notifications');pendingRequests=data.new_requests;const badge=document.querySelector('[data-page=contacts] .nav-count');if(badge){badge.textContent=String(pendingRequests);badge.hidden=!pendingRequests;badge.setAttribute('aria-label',pendingRequests+' nieuwe aanvragen');}}
 catch(error){if(error.status===401)expired();}
}
window.setInterval(pollNotifications,60000);
window.addEventListener('focus',pollNotifications);
async function signedIn(account){
 user=account;workspace=null;tenants=[];contacts=[];
 if(agency()){await loadAgency();page=['contacts','trials','partners'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'tenants';if(page==='contacts')({contacts}=await request('contacts'));}
 else{workspace=await request('workspace');const view=new URLSearchParams(location.search).get('view');page=view==='emails'?'emails':view==='bookings'?'bookings':view==='calendar'?'calendar':view==='subscription'?'subscription':view==='crm'&&crmAvailable()?'crm':'overview';}
 if(agency()&&['calendar','bookings','crm','emails'].includes(new URLSearchParams(location.search).get('view'))&&new URLSearchParams(location.search).get('tenant')){workspace=await request('workspace',undefined,{tenant:new URLSearchParams(location.search).get('tenant')});page=new URLSearchParams(location.search).get('view');}
 render();
}
async function refresh(){
 if(agency()){await loadAgency();if(page==='contacts')({contacts}=await request('contacts'));}
 if(workspace)workspace=await request('workspace',undefined,{tenant:t().id});
 render();
}
async function navigate(next){
 if(['tenants','contacts','trials','partners'].includes(next)&&!agency())return;
 if(next==='contacts')({contacts}=await request('contacts'));
 if(!workspace&&!['tenants','contacts','trials','partners','security'].includes(next))return;
 if(next==='crm'&&workspace){const id=t().id;const fresh=await request('workspace',undefined,{tenant:id});if(t()?.id!==id)return;workspace=fresh;}
 page=next;render();window.scrollTo(0,0);
}
function render(){
 document.title=`${labels[page]||'Overzicht'} · Afspraakboeken.be`;
 const nav=workspace?[['overview','grid'],['calendar','calendar'],['bookings','calendar'],['services','layers'],...(crmAvailable()?[['crm','kanban']]:[]),['customercrm','users'],['marketing','grid'],['widget','code'],['settings','clock'],['branding','settings'],['emails','mail'],...(t().trial?[['subscription','clock']]:[])]:[];
 const link=([key,symbol])=>`<button class="nav-link ${page===key?'active':''}" data-page="${key}" ${page===key?'aria-current="page"':''}>${icon(symbol)}${labels[key]}${key==='customercrm'&&!t().settings.features.crmPlus?'<small class="crm-nav-extra">Extra module</small>':''}${key==='crm'?`<span class="nav-count" aria-label="${workspace.board_unread||0} ongelezen aanvragen" ${workspace.board_unread?'':'hidden'}>${workspace.board_unread||0}</span>`:''}${key==='contacts'?`<span class="nav-count" aria-label="${pendingRequests} nieuwe aanvragen" ${pendingRequests?'':'hidden'}>${pendingRequests}</span>`:''}</button>`;
 app.innerHTML=`<div class="app-shell"><aside class="sidebar">${logo()}<div class="workspace-label"><strong>${workspace?esc(t().name):'Afspraakboeken.be · agency'}</strong><small>${agency()?'Superadminomgeving':'Jouw bedrijfsomgeving'}</small></div>${agency()?`<div class="nav-label">Agency</div>${link(['tenants','users'])}${link(['contacts','mail'])}${link(['trials','clock'])}${link(['partners','users'])}`:''}${nav.length?`<div class="nav-label">Jouw werkplek</div>${nav.map(link).join('')}`:''}<div class="sidebar-bottom"><strong>${esc(user.name)}</strong><small>${esc(user.email)}</small>${link(['security','lock'])}<button class="nav-link" data-action="logout">Afmelden</button></div></aside><main class="app-main"><header class="topbar"><div class="flex"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Menu openen">${icon('menu')}</button><span class="breadcrumb">Jouw werkplek / <strong>${labels[page]}</strong></span></div><div class="flex">${agency()&&tenants.length?`<select id="workspace-select" class="workspace-select" aria-label="Klantomgeving openen"><option value="">Kies een klantomgeving</option>${tenants.map(x=>`<option value="${x.id}" ${workspace&&x.id===t().id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}${agency()?pill('Superadmin','orange'):pill('Beheerder')}</div></header>${workspace&&!agency()?trialBanner(t()):''}<div class="content">${renderPage()}</div></main></div>`;
 if(page==='crm'&&workspace&&document.querySelector('.crm-view'))void markBoardSeen();
 if(page==='calendar'&&workspace&&document.getElementById('google-calendar'))mountGoogleCalendar(document.getElementById('google-calendar'),t(),handleError);
 if(page==='emails'&&workspace){const tenantId=t().id;mountReminders(document.getElementById('reminders-root'),t(),user,result=>{if(t()?.id===tenantId){workspace.tenant.settings.appointmentReminders=result.settings;workspace.tenant.revision=result.revision;}},handleError);}
 if(page==='partners'&&agency())mountPartnerAdmin(document.getElementById('partner-admin'),handleError);
 if(page==='marketing'&&workspace)mountMarketing(document.getElementById('marketing-root'),t(),handleError);
 if(page==='customercrm'&&workspace)mountCRM(document.getElementById('customer-crm'),t(),handleError);
}
function renderPage(){if(t()?.trial?.expired&&!agency()&&!['subscription','security','customercrm'].includes(page))return expiredTrialPage();return ({marketing:()=>'<section id="marketing-root"></section>',partners:()=>'<section id="partner-admin"></section>',tenants:tenantsPage,contacts:contactsPage,trials:()=>trialsPage(tenants,mailSetup,cronStatus),subscription:()=>subscriptionPage(t()),overview:overviewPage,services:servicesPage,bookings:bookingsPage,calendar:calendarPage,crm:crmPage,customercrm:()=>'<section id="customer-crm"></section>',settings:settingsPage,branding:brandingPage,widget:widgetPage,emails:emailsPage,security:securityPage}[page]||overviewPage)();}
function tenantsPage(){
 const monthly=tenants.filter(x=>x.active&&x.subscription.type==='monthly'),lifetime=tenants.filter(x=>x.active&&x.subscription.type==='lifetime');
 return `${header('Jouw klanten. Eén overzicht.','Maak accounts aan, kies hun mogelijkheden en activeer ze wanneer jij klaar bent.',button(icon('plus')+' Klant toevoegen','tenant-new','primary'))}<div class="stats"><div class="stat"><span>Bedrijfsaccounts</span><strong>${tenants.length}</strong><small>Alles centraal beheerd</small></div><div class="stat"><span>Maandelijks actief</span><strong>${monthly.length}</strong><small>${money(monthly.reduce((n,x)=>n+x.subscription.monthlyAmount,0))} afgesproken · geen betalingen</small></div><div class="stat"><span>Lifetime actief</span><strong>${lifetime.length}</strong><small>Zolang de klant bij jouw agency blijft</small></div></div>${tenants.length?`<div class="grid-3">${tenants.map(x=>`<article class="panel tenant-card"><div class="flex between"><div class="avatar">${esc(x.name.slice(0,2).toUpperCase())}</div>${pill(x.active?'Actief':'Nog niet actief',x.active?'':'grey')}</div><div><h2>${esc(x.name)}</h2><small>${esc(x.sector)} · ${esc(x.email)}</small></div><div>${pill(x.trial&&!x.trial.converted_at?'Gratis proefperiode':x.subscription.type==='lifetime'?'Lifetime':x.subscription.type==='annual'?'Jaarlijks':'Maandelijks','orange')} <strong>${x.trial&&!x.trial.converted_at?'€0 tijdens proefperiode':money(x.subscription.type==='lifetime'?x.subscription.lifetimeAmount:x.subscription.type==='annual'?x.subscription.monthlyAmount*12:x.subscription.monthlyAmount)}</strong><p class="field-help">Facturatie via jouw eigen administratie.</p></div><div class="card-actions">${button('Open omgeving','tenant-open','small primary',`data-id="${x.id}"`)}${button('Administratie','tenant-admin','small',`data-id="${x.id}"`)}${button('Activatielink','tenant-invite','small',`data-id="${x.id}"`)}</div></article>`).join('')}</div>`:`<section class="panel empty">${icon('users')}<h2>Een goede start, voor elke klant.</h2><p>Voeg je eerste bedrijf toe. De klant krijgt een eigen omgeving en een persoonlijke activatielink.</p>${button('Eerste klant toevoegen','tenant-new','primary')}</section>`}`;
}
function bookingTable(list){return `<div class="table-wrap"><table><thead><tr><th>Klant</th><th>Dienst</th><th>Moment</th><th>Status</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><strong>${esc(b.name)}</strong><small>${esc(b.email)}</small></td><td>${esc(b.serviceName)}<small>${b.duration} min</small></td><td>${dateLabel(b.date)}<small>${esc(b.time)}</small></td><td>${bookingStatus(b)}</td><td>${button('Bekijken','booking-detail','small',`data-id="${b.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nog geen afspraken in dit overzicht.</td></tr>'}</tbody></table></div>`;}
function overviewPage(){
 if(intake(t()).mode==='request'){
  const leads=companyLeads();
  return `${header(`Goed geregeld, ${esc(t().name)}.`,'Je aanvragen en volgende stappen, in één oogopslag.',`<a class="btn primary" href="?mode=book&tenant=${t().id}" target="_blank" rel="noopener">Aanvraagformulier </a>`)}<div class="stats"><div class="stat"><span>Nieuwe aanvragen</span><strong>${leads.filter(l=>l.stage==='new').length}</strong><small>Klaar om op te volgen</small></div><div class="stat"><span>In opvolging</span><strong>${leads.filter(l=>l.stage==='contacted').length}</strong><small>Contact gelegd</small></div><div class="stat"><span>Ingepland</span><strong>${leads.filter(l=>l.bookingId&&workspace.bookings.some(b=>b.id===l.bookingId&&b.status==='confirmed')).length}</strong><small>Met een bevestigde afspraak</small></div></div><section class="panel table-panel"><div class="panel-head"><h2>Laatste aanvragen</h2>${button('Aanvragen bekijken','page-crm','small')}</div><div class="table-wrap"><table><thead><tr><th>Contactpersoon</th><th>Aanvraag</th><th>Ontvangen</th><th></th></tr></thead><tbody>${leads.slice(0,8).map(l=>`<tr><td><strong>${esc(l.name)}</strong><small>${esc(l.email)}</small></td><td>${esc(l.serviceName||'Contactaanvraag')}</td><td>${dateLabel(l.createdAt.slice(0,10))}</td><td>${button('Bekijken','lead-detail','small',`data-id="${l.id}"`)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nog geen aanvragen. Deel je formulier of plaats de widget op je website.</td></tr>'}</tbody></table></div></section>`;
 }
 const upcoming=activeBookings().filter(b=>b.date>=TODAY()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 return `${header(`Goed geregeld, ${esc(t().name)}.`,'Je afspraken en volgende stappen, in één oogopslag.',`<a class="btn primary" href="?mode=book&tenant=${t().id}" target="_blank" rel="noopener">${intake(t()).mode==='request'?'Aanvraagformulier':'Boekingspagina'} </a>`)}${!t().active?'<div class="notice warning section-gap">Dit bedrijfsaccount is nog niet actief. De openbare boekingspagina blijft gesloten tot je het activeert via Administratie.</div>':''}<div class="stats section-gap"><div class="stat"><span>Komende 7 dagen</span><strong>${upcoming.filter(b=>b.date<=addDays(TODAY(),7)).length}</strong><small>Geplande afspraken</small></div><div class="stat"><span>Boekbare diensten</span><strong>${workspace.services.filter(s=>s.active).length}</strong><small>In jouw aanbod</small></div><div class="stat"><span>Nog op te volgen</span><strong>${activeBookings().filter(b=>b.stage==='new'&&!companyLeads().some(l=>l.bookingId===b.id)).length+companyLeads().filter(l=>l.stage==='new').length}</strong><small>Nieuwe aanvragen en afspraken</small></div></div><section class="panel table-panel"><div class="panel-head"><h2>Eerstvolgende afspraken</h2>${button('Alle afspraken','page-bookings','small')}</div>${bookingTable(upcoming.slice(0,8))}</section>`;
}
function servicesPage(){return `${header('Diensten die voor je werken.','Een helder aanbod voor afspraken en aanvragen.',button(icon('plus')+' Dienst toevoegen','service-new','primary'))}${workspace.services.length?`<div class="grid-3">${workspace.services.map(s=>`<article class="panel service-card">${serviceVisual(s.image)}<div class="service-body"><div class="flex between"><small>Dienst</small>${pill(s.active?'Boekbaar':'Verborgen',s.active?'':'grey')}</div><h2>${esc(s.name)}</h2><p class="description">${esc(s.description)}</p><div class="service-meta"><span>${s.duration} min</span><span>+ ${s.buffer} min buffer</span><strong>${money(s.price)}</strong></div>${button('Dienst bewerken','service-edit','',`data-id="${s.id}"`)}</div></article>`).join('')}</div>`:'<div class="panel empty"><h2>Wat kunnen klanten bij jou boeken?</h2><p>Voeg een dienst toe met een duidelijke omschrijving, tijdsduur en prijs.</p></div>'}`;}
function bookingsPage(){return `${header('Elke afspraak, op één plek.','Alle gegevens bij elkaar. Zo kun je je klant goed helpen.')}<div class="panel table-panel">${bookingTable(workspace.bookings)}</div><p class="field-help section-gap">De laatste ${workspace.booking_limit} afspraken worden geladen. Tijden in België · Europe/Brussels.</p>`;}
function calendarPage(){const list=activeBookings().filter(b=>b.date===calendarDay).sort((a,b)=>a.time.localeCompare(b.time));return `${header('Een agenda die met je meewerkt.','Afspraken en geblokkeerde dagen worden centraal bewaard.',button('Beschikbaarheid instellen','page-settings'))}<section class="panel"><div class="panel-head"><div class="flex"><button class="btn small calendar-nav" data-action="day-prev" aria-label="Vorige dag">Vorige</button><input id="calendar-day" type="date" value="${calendarDay}" aria-label="Dag bekijken" style="max-width:175px"><button class="btn small calendar-nav" data-action="day-next" aria-label="Volgende dag">Volgende</button></div>${pill(t().settings.blocks.includes(calendarDay)?'Geblokkeerd':'Dagoverzicht',t().settings.blocks.includes(calendarDay)?'orange':'grey')}</div><h2>${dateLabel(calendarDay,{weekday:'long',day:'numeric',month:'long'})}</h2>${bookingTable(list)}</section><div id="google-calendar"></div><p class="field-help section-gap">Automatische afspraakbevestigingen per e-mail zijn nog niet aangesloten.</p>`;}
function crmPage(){return `<section class="crm-view ${crmFocus?'crm-focus':''}">${header('Je aanvragen, overzichtelijk bij elkaar.','Nieuwe aanvragen komen automatisch in de eerste kolom. Verplaats een kaart om de opvolging bij te houden.',`<div class="crm-actions">${button('Kolommen beheren','crm-columns')}${button(`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/></svg>${crmFocus?'Normale weergave':'Volledig scherm'}`,'crm-focus')}${button('Lead toevoegen','lead-new','primary')}</div>`)}${crmBoard(workspace)}</section>`;}
function settingsPage(){const s=t().settings;return `${header('Op jouw ritme.','Bepaal wanneer je klanten een afspraak kunnen boeken.')}<div class="grid-2"><section class="panel"><h2>Wekelijkse beschikbaarheid</h2><form id="hours-form" class="fields section-gap">${['Zondag','Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag'].map((day,i)=>`<div class="day-row"><label class="check"><input type="checkbox" name="open_${i}" ${s.hours[i].open?'checked':''}>${day}</label><label><span class="field-help">Van</span><input name="start_${i}" type="time" value="${s.hours[i].start}" required aria-label="${day} vanaf"></label><label><span class="field-help">Tot</span><input name="end_${i}" type="time" value="${s.hours[i].end}" required aria-label="${day} tot"></label></div>`).join('')}<label>Minimale voorbereiding (uren)<input type="number" name="notice" value="${s.notice}" min="0" max="168" required></label><label>Locatie of afspraakomschrijving<input name="location" value="${esc(s.location)}" maxlength="200"></label>${fieldError()}<button type="submit" class="btn primary">Beschikbaarheid opslaan</button></form></section><section class="panel"><h2>Een dag vrijhouden</h2><p class="sub">Een verlofdag of een volle planning? Blokkeer die dag voor nieuwe afspraken.</p><form id="block-form" class="fields section-gap"><label>Dag<input name="date" type="date" required min="${TODAY()}"></label>${fieldError()}<button type="submit" class="btn">Dag blokkeren</button></form><div class="section-gap">${s.blocks.map(day=>`<div class="block-tag"><span>${dateLabel(day,{day:'numeric',month:'long',year:'numeric'})}</span>${button('Vrijgeven','block-remove','small',`data-date="${day}"`)}</div>`).join('')||'<small>Er zijn nog geen dagen geblokkeerd.</small>'}</div><p class="field-help section-gap">Bestaande afspraken blijven staan. Annuleer ze afzonderlijk als dat nodig is.</p></section></div>`;}
function brandFields(brand){return `<div class="color-grid">${[['primary','Hoofdkleur'],['secondary','Accentkleur'],['background','Achtergrond']].map(([key,label])=>`<label>${label}<input name="${key}" type="color" value="${brand[key]}"></label>`).join('')}</div><label>Hoofdlettertype<select name="font">${Object.entries(BRAND_FONTS).map(([key,f])=>`<option value="${key}" ${brand.font===key?'selected':''}>${f.label}</option>`).join('')}</select></label>`;}
function brandStyle(brand){return Object.entries(brandVariables(brand)).map(([key,value])=>`${key}:${value}`).join(';');}
function brandingPage(){return `${header('Jouw naam. Jouw kleuren.','Een boekingservaring die past bij jouw zaak.')}<div class="grid-2"><section class="panel"><form id="brand-form" class="fields">${brandFields(t().settings.branding)}${fieldError()}<button type="submit" class="btn primary">Huisstijl opslaan</button></form><div class="brand-preview" id="brand-preview" style="${brandStyle(t().settings.branding)}"><small>Jouw boekingspagina</small><strong>${esc(t().name)}</strong><p>Een moment, helemaal voor jouw klant.</p><span class="section-gap">Kies je moment </span></div></section>${agency()?modulePanel():'<section class="panel"><h2>Voelt als een deel van je website.</h2><p class="sub">Deze kleuren en dit lettertype verschijnen in elke stap van de boeking. Je beheeromgeving houdt haar rustige, vaste uitstraling.</p></section>'}</div>`;}
const moduleLabels={crmPlus:['CRM-uitbreiding','Betaalde module: contacten, klantfiches, eigen formuliervragen, notities, opvolgacties en export. Facturatie regel je zelf.'],prices:['Prijzen tonen','Toon de prijs bij elke boekbare dienst.'],media:['Afbeeldingen en video','Meer informatie bij een dienst.'],address:['Adres opvragen','Handig bij afspraken op locatie.'],notes:['Opmerkingen','Laat klanten iets meegeven bij hun afspraak.'],crm:['Aanvragen','Het eenvoudige aanvraagbord.'],tracking:['Campagnemeting','Een lead_submitted- of booking_completed-event na toestemming; geen persoonsgegevens of pixels.']};
function modulePanel(){return `<section class="panel"><h2>Modules voor deze klant</h2><form id="modules-form">${Object.entries(moduleLabels).map(([key,[label,description]])=>`<label class="module-row"><span><strong>${label}</strong><small>${description}</small></span><input name="${key}" type="checkbox" ${t().settings.features[key]?'checked':''}></label>`).join('')}${fieldError()}<button type="submit" class="btn primary section-gap">Modules opslaan</button></form></section>`;}
function widgetCode(mode=t().settings.widgetMode||'drawer'){const b=t().settings.branding;return `<script src="${new URL('./widget.js?v=0.20.0',location.href)}" data-account="${t().id}" data-mode="${mode}" data-label="${intake(t()).mode==='request'?'Neem contact op':'Boek je afspraak'}" data-primary="${b.primary}" data-secondary="${b.secondary}" data-background="${b.background}" data-font="${b.font}"><\/script>`;}
function widgetPage(){return `${header('Eenvoudig op jouw website.','Plaats de widget op WordPress of een andere website.')}<details class="panel widget-section" open><summary><strong>1. Werkwijze</strong><small>${intake(t()).mode==='booking'?'Direct een afspraak boeken':'Eerst een aanvraag ontvangen'}</small></summary>${intakePanel(t())}</details><details class="panel widget-section"><summary><strong>2. Weergave</strong><small>${t().settings.widgetMode==='inline'?'Formulier direct op je website':'Openen via een knop'}</small></summary><form id="widget-form" class="fields"><label class="check"><input type="checkbox" name="showButton" id="widget-show-button" ${(t().settings.widgetMode||'drawer')!=='inline'?'checked':''}>Toon eerst een knop</label><p class="field-help">Uitgevinkt staat het formulier meteen op je website. Ideaal als slim contactformulier.</p><label id="widget-button-options" ${t().settings.widgetMode==='inline'?'hidden':''}>Hoe opent de knop het formulier?<select name="mode" id="widget-mode"><option value="drawer" ${t().settings.widgetMode!=='popup'?'selected':''}>Als zijpaneel</option><option value="popup" ${t().settings.widgetMode==='popup'?'selected':''}>Als pop-up</option></select></label><p id="widget-display-summary" class="notice">${t().settings.widgetMode==='inline'?'Het formulier verschijnt direct op de pagina.':'Het formulier opent na een klik op de knop.'}</p>${fieldError()}<p id="widget-save-status" class="field-help" role="status">Wijzigingen worden automatisch opgeslagen.</p></form><p class="field-help section-gap">Je keuze wordt automatisch opgeslagen. Vervang daarna de widgetcode op je website. Dit geldt ook na wijzigingen aan de knop of huisstijl. Het formulier zelf volgt automatisch je opgeslagen werkwijze.</p></details>${fieldsPanel(t())}<section class="panel section-gap"><h2>Plaats het formulier op je website</h2><label class="fields section-gap">Widgetcode<textarea id="widget-code" class="code" readonly rows="5">${esc(widgetCode())}</textarea></label>${button('Code kopiëren','copy-widget','primary section-gap')}</section><section class="panel section-gap"><h2>Of deel je eigen link.</h2><p class="sub">Handig in een e-mail, op sociale media of achter een knop op je website.</p><a class="btn primary section-gap" href="?mode=book&tenant=${t().id}" target="_blank" rel="noopener">${intake(t()).mode==='request'?'Aanvraagformulier':'Boekingspagina'} openen </a>${!t().active?'<div class="notice warning section-gap">Activeer dit account voordat je de boekingspagina deelt.</div>':''}</section>`;}
function emailsPage(){return `<section id="reminders-root" class="reminder-page"></section><details class="panel section-gap"><summary>Meldingen en afspraakbevestigingen</summary><p class="field-help">Meldingen over nieuwe aanvragen en boekingen gaan naar <strong>${esc(t().email)}</strong>.</p>${workspace.notification_mail?.configured===false?'<p class="notice warning">De verzendmailbox is nog niet ingesteld.</p>':''}${workspace.notification_mail?.pending?`<p class="field-help">Er wachten ${workspace.notification_mail.pending} meldingen op verzending of een nieuwe poging.</p>`:''}${workspace.notification_mail?.attention?'<p class="notice warning">Er zijn meldingen waarvan de verzending aandacht nodig heeft. Neem contact op met Afspraakboeken.be.</p>':''}<p class="field-help">De onmiddellijke afspraakbevestiging per e-mail is nog niet aangesloten. Hieronder bewaar je alvast je tekst; automatische herinneringen stel je hierboven in.</p><form id="email-form" class="fields section-gap"><label>Onderwerp<input name="subject" value="${esc(t().settings.subject)}" maxlength="180" required></label><label>Bericht<textarea name="message" maxlength="4000" rows="5" required>${esc(t().settings.message)}</textarea></label><p class="field-help">Invulvelden: {{bedrijf}}, {{voornaam}}, {{dienst}}, {{datum}} en {{tijd}}.</p>${fieldError()}<button type="submit" class="btn">Tekst bewaren</button></form></details>`;}
function securityPage(){return `${header('Jouw account.','Je meldt je aan met '+esc(user.email)+'.')}<form id="password-form" class="panel fields" style="max-width:560px"><h2>Wachtwoord wijzigen</h2><label>Huidig wachtwoord<input type="password" name="current_password" autocomplete="current-password" required maxlength="72"></label><label>Nieuw wachtwoord<input type="password" name="password" autocomplete="new-password" required minlength="12" maxlength="72"></label><label>Herhaal nieuw wachtwoord<input type="password" name="repeat_password" autocomplete="new-password" required minlength="12" maxlength="72"></label><p class="field-help">Gebruik een lange, unieke wachtzin. Na het wijzigen meld je opnieuw aan.</p>${fieldError()}<button type="submit" class="btn primary">Wachtwoord wijzigen</button></form>`;}
function contactsPage(){return `${header('Nieuwe kansen voor Afspraakboeken.be.','Aanvragen van de website, alleen zichtbaar voor jou.')}<div class="stack">${contacts.map(c=>`<article class="panel contact-row"><div class="flex between wrap"><div><h2>${esc(c.company)}</h2><small>${esc(c.name)} · ${esc(c.sector)} · ${dateLabel(c.created_at.slice(0,10))}</small></div><select data-contact-status="${c.id}" aria-label="Status van aanvraag ${esc(c.company)}" style="width:auto"><option value="new" ${c.status==='new'?'selected':''}>Nieuw</option><option value="contacted" ${c.status==='contacted'?'selected':''}>Gecontacteerd</option><option value="archived" ${c.status==='archived'?'selected':''}>Gearchiveerd</option></select></div><p><a href="mailto:${esc(c.email)}">${esc(c.email)}</a>${c.phone?' · '+esc(c.phone):''}</p><p class="contact-message">${esc(c.message)}</p>${c.notification&&c.notification!=='contact.mail_sent'?`<small class="field-help">${c.notification==='contact.mail_failed'?'E-mailmelding niet verstuurd. De aanvraag is hier opgeslagen.':'E-mailmelding nog niet actief. De aanvraag is hier opgeslagen.'}</small>`:''}</article>`).join('')||'<section class="panel empty"><h2>Hier begint de opvolging.</h2><p>Nieuwe aanvragen van de homepagina en registratiepagina verschijnen automatisch in dit overzicht.</p></section>'}</div>`;}

function serviceEditor(id){const s=workspace.services.find(s=>s.id===id)||{name:'',category:'',description:'',duration:30,buffer:0,price:0,active:true,image:'',video:''};modal(id?'Dienst bewerken':'Nieuwe dienst',`<form id="service-form" class="fields" data-id="${s.id||''}" data-revision="${s.revision||1}"><label>Naam<input name="name" value="${esc(s.name)}" maxlength="120" required></label><div class="grid-3"><label>Duur (min)<input name="duration" type="number" min="15" max="480" value="${s.duration}" required></label><label>Buffer (min)<input name="buffer" type="number" min="0" max="180" value="${s.buffer}" required></label><label>Prijs (€)<input name="price" type="number" min="0" max="100000" step=".01" value="${s.price}" required></label></div><label>Uitleg voor je klant<textarea name="description" maxlength="3000" required>${esc(s.description)}</textarea></label><fieldset class="service-upload"><legend>Afbeelding <span class="field-help">(optioneel)</span></legend><div data-image-preview>${serviceVisual(s.image)}</div><input name="image" type="hidden" value="${esc(s.image)}"><label>Afbeelding kiezen<input name="imageFile" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="service-image-help"></label><p class="field-help" id="service-image-help">JPG, PNG of WebP · maximaal 5 MB. Zonder foto gebruiken we een rustige standaardafbeelding.</p><p class="field-help" data-image-status role="status">${s.image?'Je huidige afbeelding blijft behouden tot je een andere kiest.':'De standaardafbeelding wordt gebruikt.'}</p><button type="button" class="btn small" data-image-remove>Afbeelding verwijderen</button></fieldset><label>Video (https-link)<input name="video" type="url" value="${esc(s.video)}" maxlength="1000"></label><label class="check"><input name="active" type="checkbox" ${s.active?'checked':''}>Zichtbaar en boekbaar</label>${formButtons('Dienst opslaan')}</form>`);const form=document.getElementById('service-form');form.uploadImage=mountServiceImage(form);}
function tenantEditor(){modal('Een nieuwe klant',`<form id="tenant-form" class="fields"><label>Bedrijfsnaam<input name="name" maxlength="120" required></label><div class="grid-2"><label>Naam beheerder<input name="admin_name" maxlength="120" required autocomplete="off"></label><label>E-mail beheerder<input name="email" type="email" maxlength="190" required autocomplete="off"></label></div><label>Sector<select name="sector" required><option value="" disabled selected>Kies een sector</option>${SECTORS.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><div class="grid-2"><label>Formule<select name="plan_type"><option value="monthly">Maandelijks</option><option value="annual">Jaarlijks · maandbedrag × 12</option><option value="lifetime">Lifetime · zolang agencyklant</option></select></label><label>Afgesproken bedrag excl. btw (€)<input name="amount" type="number" min="0" max="100000" step=".01" value="0" required></label></div><p class="field-help">Vul bij een maand- of jaarabonnement het maandbedrag in. Het jaarbedrag is 12 × dit bedrag; bij lifetime vul je het eenmalige bedrag in.</p>${brandFields({primary:'#264653',secondary:'#2a9d8f',background:'#f8fafb',font:'dm-sans'})}<div class="notice">Het account start inactief. ${mailSetup?.configured?'De beheerder ontvangt een welkomstmail met een persoonlijke activatielink.':'Automatische welkomstmails staan nog niet aan. Je krijgt een activatielink om zelf te delen.'} Jij regelt de factuur en activeert het bedrijfsaccount.</div>${formButtons('Klant aanmaken')}</form>`);}
function welcomeMessage(mail){
 if(mail?.status==='sent')return `Welkomstmail verstuurd naar ${esc(mail.recipient)}.`;
 if(mail?.status==='failed')return 'De welkomstmail kon niet worden verstuurd. Controleer de verzendmailbox of deel de activatielink persoonlijk.';
 if(mail?.status==='not_configured')return 'Er is nog geen verzendmailbox ingesteld. Er is geen e-mail verstuurd. Je kunt de activatielink persoonlijk delen.';
 return 'Deel de activatielink persoonlijk met de juiste beheerder. Er is geen e-mail verstuurd.';
}
function invitationFields(url){return `<textarea id="invite-url" class="invite-url" readonly aria-label="Persoonlijke activatielink">${esc(url)}</textarea>${button('Activatielink kopiëren','copy-invite','primary')}`;}
function tenantAdmin(id){
 const x=tenants.find(x=>x.id===id),s=x.subscription,b=s.billing,admin=x.admin||{name:'',email:x.email};
 const last=x.welcome?.status==='sent'?'De laatste welkomstmail is verstuurd.':x.welcome?.status==='failed'?'De laatste welkomstmail kon niet worden verstuurd.':'Er is nog geen welkomstmail verstuurd.';
 modal('Administratie · '+x.name,`<form id="tenant-admin-form" data-id="${id}" data-revision="${x.revision}" class="fields">
 <div class="grid-2"><label>Naam beheerder<input value="${esc(admin.name||'—')}" readonly></label><label>E-mailadres account<input type="email" value="${esc(admin.email)}" readonly></label></div>
 <p class="field-help">Dit is het aanmeldadres van de beheerder. De welkomstmail gaat naar dit adres.</p>
 <div class="notice"><div id="welcome-delivery" class="stack" role="status" aria-live="polite"><p>${mailSetup?.configured?last:'Automatische e-mails staan nog niet aan. Stel eerst de verzendmailbox in op Hostinger.'}</p></div><div class="section-gap">${button('Welkomstmail versturen','tenant-welcome','small',`data-id="${id}" ${mailSetup?.configured?'':'disabled'}`)}</div><p class="field-help">Een nieuwe welkomstmail vervangt eerdere activatielinks. Het bestaande wachtwoord blijft werken.</p></div>
 <label class="check"><input name="active" type="checkbox" ${x.active?'checked':''}>Bedrijfsaccount actief</label><p class="field-help">Inactief betekent: geen toegang tot de beheeromgeving en geen nieuwe boekingen. Bestaande gegevens blijven bewaard.</p>
 <label class="check"><input name="crmPlus" type="checkbox" ${x.settings.features.crmPlus?'checked':''}>CRM-uitbreiding actief</label><p class="field-help">Contacten, notities en opvolgacties als extra module. Je factureert de meerprijs zelf. Uitschakelen behoudt alle gegevens en de export.</p>
 <label>Formule<select name="plan_type"><option value="monthly" ${s.type==='monthly'?'selected':''}>Maandelijks</option><option value="annual" ${s.type==='annual'?'selected':''}>Jaarlijks · afgesproken maandbedrag × 12</option><option value="lifetime" ${s.type==='lifetime'?'selected':''}>Lifetime · zolang agencyklant</option></select></label>
 <div class="grid-2"><label>Afgesproken maandbedrag excl. btw (€)<input type="number" name="monthlyAmount" min="0" max="100000" step=".01" value="${s.monthlyAmount}" required></label><label>Eenmalig bedrag excl. btw (€)<input type="number" name="lifetimeAmount" min="0" max="100000" step=".01" value="${s.lifetimeAmount}" required></label></div>
 <p class="field-help">Bij jaarlijkse facturatie is het jaarbedrag 12 × het afgesproken maandbedrag. Je verstuurt de factuur apart. Deze bedragen registreren geen ontvangen betaling.</p>
 <details open><summary>Facturatiegegevens en interne notities</summary><div class="fields section-gap"><label>E-mailadres voor facturen<input type="email" name="billingEmail" value="${esc(b.email||'')}" placeholder="${esc(admin.email)}" maxlength="190" autocomplete="off"></label><p class="field-help">Mag afwijken van het accountadres. Facturen verstuur je zelf via je eigen administratie.</p>${[['legalName','Bedrijfsnaam op factuur'],['vatNumber','Btw-nummer'],['address','Facturatieadres'],['invoiceReference','Factuurreferentie']].map(([key,label])=>`<label>${label}<input name="${key}" value="${esc(b[key]||'')}" maxlength="${key==='address'?250:key==='vatNumber'?50:key==='invoiceReference'?100:150}"></label>`).join('')}<label>Interne notitie<textarea name="notes" maxlength="1000">${esc(b.notes||'')}</textarea></label></div></details>${formButtons('Administratie opslaan')}</form>`);
}
function inviteDialog(url,mail){modal(mail?.status==='sent'?'Je klant is welkom.':'De persoonlijke activatielink',`<div class="stack"><div class="notice ${mail&&mail.status!=='sent'?'warning':''}" role="status">${welcomeMessage(mail)}</div><p>De klant kiest via deze link zelf een wachtwoord. De link werkt één keer en vervalt na 24 uur.</p>${invitationFields(url)}<p class="field-help">Het bedrijfsaccount moet ook actief staan om te kunnen aanmelden.</p></div>`);}
function bookingDetail(id){const b=workspace.bookings.find(b=>b.id===id);modal('Afspraakdetails',`<div class="stack"><div class="flex between"><h2>${esc(b.serviceName)}</h2>${bookingStatus(b)}</div>${originBadge(b)}<dl class="detail-grid">${[['Klant',b.name],['E-mail',b.email],['Telefoon',b.phone],['Moment',dateLabel(b.date)+' om '+b.time],['Duur',b.duration+' min + '+b.buffer+' min buffer'],['Prijs',money(b.price)],['Adres',b.address],['Opmerking',b.notes],['Campagne',b.origin?.campaign||b.campaign]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'—')}</dd>`).join('')}</dl><section id="booking-reminders"></section><div class="booking-detail-actions"><a class="btn primary" href="${esc('mailto:'+encodeURIComponent(b.email)+'?subject='+encodeURIComponent('Je afspraak: '+b.serviceName+' · '+dateLabel(b.date)+' om '+b.time))}">Contacteer je klant</a><p class="field-help">Opent je eigen e-mailprogramma.</p>${b.status==='confirmed'?`${button('Afspraak verplaatsen','booking-move','',`data-id="${b.id}"`)}<div class="booking-secondary-action">${button('Afspraak annuleren','booking-cancel-confirm','booking-cancel-link',`data-id="${b.id}"`)}</div>`:''}</div></div>`);mountBookingReminders(document.getElementById('booking-reminders'),t().id,b.id);}
let leadSlotGeneration=0;
async function loadLeadSlots(){
 const form=document.getElementById('lead-plan-form');if(!form)return;
 const generation=++leadSlotGeneration,service=form.elements.service.value,date=form.elements.date.value,select=document.getElementById('lead-time'),status=document.getElementById('lead-slot-status'),save=document.getElementById('lead-plan-submit');
 select.disabled=true;save.disabled=true;select.innerHTML='<option value="">Kies een vrij moment</option>';
 if(!service||!date){status.textContent='Kies eerst een dienst en datum.';return;}
 status.textContent='Vrije momenten ophalen…';
 try{const r=await request('lead/slots',undefined,{tenant:t().id,id:form.dataset.id,service,date});if(generation!==leadSlotGeneration||!form.isConnected)return;
  select.innerHTML='<option value="">Kies een vrij moment</option>'+r.times.map(time=>`<option value="${esc(time)}">${esc(time)}</option>`).join('');select.disabled=!r.times.length;status.textContent=r.times.length?'Kies het afgesproken tijdstip.':'Geen vrije momenten. Kies een andere dag of pas je beschikbaarheid aan.';
 }catch(e){if(generation===leadSlotGeneration&&form.isConnected)status.textContent=e.message;}
}
async function saveSettings(settings){await request('tenant/save',{tenant:t().id,revision:t().revision,settings});await refresh();}
async function act(action,el){
 if(action.startsWith('page-'))return navigate(action.slice(5));
 if(action==='close')return closeModal();
 if(action==='menu')return document.querySelector('.sidebar').classList.toggle('open');
 if(action==='logout'){await request('logout',{});user=null;workspace=null;setCsrf('');return renderLogin(signedIn);}
 if(action==='trial-convert'&&agency())return modal('Abonnement activeren',conversionForm(tenants.find(x=>x.id===el.dataset.id)));
 if(action==='tenant-new'&&agency())return tenantEditor();
 if(action==='tenant-admin'&&agency())return tenantAdmin(el.dataset.id);
 if(action==='tenant-welcome'&&agency()){
  if(el.disabled)return;el.disabled=true;const label=el.textContent;el.textContent='Versturen…';
  try{const r=await request('tenant/welcome',{tenant:el.dataset.id});await refresh();const target=document.getElementById('welcome-delivery');if(target)target.innerHTML=`<p>${welcomeMessage(r.mail)}</p>${r.mail.status==='sent'?'':invitationFields(r.invite_url)}`;}
  finally{el.disabled=false;el.textContent=label;}return;
 }
 if(action==='tenant-invite'&&agency()){const r=await request('tenant/invite',{tenant:el.dataset.id});return inviteDialog(r.invite_url);}
 if(action==='tenant-open'){workspace=await request('workspace',undefined,{tenant:el.dataset.id});return navigate('overview');}
 if(action==='service-new')return serviceEditor();
 if(action==='service-edit')return serviceEditor(el.dataset.id);
 if(action==='lead-new')return modal('Lead toevoegen',manualLeadForm(workspace));
 if(action==='crm-columns')return modal('Kolommen beheren',columnsForm(t()));
 if(action==='column-add'){const fields=document.getElementById('column-fields');if(fields.children.length>=12)return toast('Je kunt maximaal 12 kolommen toevoegen.');fields.insertAdjacentHTML('beforeend',columnRow({id:'c'+crypto.randomUUID().replaceAll('-','').slice(0,12),name:''}));fields.lastElementChild.querySelector('input').focus();return;}
 if(action==='crm-focus'){crmFocus=!crmFocus;render();document.querySelector('[data-action="crm-focus"]')?.focus();return;}
 if(action==='lead-detail')return modal('Aanvraagdetails',leadDetailContent(companyLeads().find(l=>l.id===el.dataset.id),workspace));
 if(action==='lead-plan')return modal('Van aanvraag naar afspraak',scheduleForm(companyLeads().find(l=>l.id===el.dataset.id),workspace.services));
 if(action==='booking-move'){const b=workspace.bookings.find(x=>x.id===el.dataset.id);modal('Afspraak verplaatsen',`<form id="booking-move-form" data-id="${b.id}" data-date="${b.date}" data-time="${b.time}" class="fields"><p>${esc(b.name)} · ${esc(b.serviceName)}</p><label>Nieuwe datum<input name="date" id="move-date" type="date" min="${TODAY()}" max="${addDays(TODAY(),60)}" required></label><label>Tijdstip<select name="time" id="move-time" required disabled><option>Kies eerst een datum</option></select></label><p class="field-help">Breng je klant zelf op de hoogte. De gekoppelde Google-agenda wordt bijgewerkt; er wordt geen e-mail verstuurd.</p>${fieldError()}<button type="submit" class="btn primary" disabled>Afspraak verplaatsen</button></form>`);return;}
 if(action==='booking-cancel-confirm'){const b=workspace.bookings.find(x=>x.id===el.dataset.id);if(!b||b.status!=='confirmed')return;modal('Afspraak annuleren?',`<form id="cancel-form" data-id="${b.id}" class="fields"><p>Wil je de afspraak van <strong>${esc(b.name)}</strong> op ${dateLabel(b.date)} om ${esc(b.time)} annuleren?</p><p class="field-help">Het tijdstip komt opnieuw vrij. Breng je klant zelf op de hoogte; er wordt geen automatische e-mail verstuurd.</p>${fieldError()}<div class="save-row wrap">${button('Afspraak behouden','booking-detail','',`data-id="${b.id}"`)}<button type="submit" class="btn danger">Ja, annuleren</button></div></form>`);document.querySelector('#cancel-form [data-action=booking-detail]').focus();return;}
 if(action==='booking-detail')return bookingDetail(el.dataset.id);
 if(action==='block-remove'){await saveSettings({blocks:t().settings.blocks.filter(d=>d!==el.dataset.date)});return toast('De dag is weer beschikbaar.');}
 if(action==='day-prev'||action==='day-next'){calendarDay=addDays(calendarDay,action==='day-prev'?-1:1);return render();}
 if(action==='question-add'){const box=document.getElementById('custom-questions');if(box.children.length>=5)return toast('Je kunt maximaal vijf vragen toevoegen.');box.insertAdjacentHTML('beforeend',questionRow());return;}
 if(action==='question-remove'){el.closest('[data-question-id]')?.remove();return;}
 if(action==='form-crm-info'){navigate('customercrm');return;}
 if(action==='copy-widget'||action==='copy-invite'){const field=document.getElementById(action==='copy-widget'?'widget-code':'invite-url');try{await navigator.clipboard.writeText(field.value);toast('Gekopieerd.');}catch{field.focus();field.select();toast('Selecteer en kopieer de tekst.');}}
}
document.addEventListener('click',event=>{if(!user)return;const el=event.target.closest('[data-action],[data-page]');if(!el)return;Promise.resolve(el.dataset.page?navigate(el.dataset.page):act(el.dataset.action,el)).catch(handleError);});
function handleError(error){if(error.status===401)expired();else toast(error.message);}
function expired(){user=null;workspace=null;tenants=[];contacts=[];setCsrf('');if(document.getElementById('modal').open)closeModal();renderLogin(signedIn,'Je sessie is verlopen. Meld je opnieuw aan.');}
document.addEventListener('session-expired',()=>{if(user)expired();});
document.addEventListener('change',async event=>{
 if(event.target.id==='move-date'){const form=event.target.form,chosen=event.target.value,select=form.querySelector('select'),save=form.querySelector('[type=submit]');select.disabled=true;save.disabled=true;try{const r=await request('booking/slots',undefined,{tenant:t().id,id:form.dataset.id,date:chosen});if(!form.isConnected||form.elements.date.value!==chosen)return;select.innerHTML=r.times.map(time=>`<option>${time}</option>`).join('')||'<option>Geen vrije momenten</option>';select.disabled=!r.times.length;save.disabled=!r.times.length;}catch(e){form.querySelector('.form-error').textContent=e.message;}return;}
 if(!user)return;const el=event.target;
 try{
  if(el.id==='workspace-select'&&el.value){workspace=await request('workspace',undefined,{tenant:el.value});return navigate('overview');}
  if(el.form?.id==='intake-form'){
   const form=el.form,mode=form.elements.intakeMode.value,serviceSelection=form.elements.serviceSelection.checked;
   document.getElementById('intake-service-option').hidden=mode!=='request';document.getElementById('intake-preview').textContent=flowLabel({mode,serviceSelection});
   const previous=intake(t()),id=t().id,status=document.getElementById('intake-save-status');
   const controls=[...form.querySelectorAll('input')];controls.forEach(c=>c.disabled=true);status.textContent='Opslaan…';form.querySelector('.form-error').textContent='';
   try{const saved=await request('tenant/save',{tenant:id,revision:t().revision,settings:{intake:{mode,serviceSelection}}});if(t()?.id===id){workspace.tenant.settings.intake={mode,serviceSelection};workspace.tenant.revision=saved.revision||workspace.tenant.revision+1;if(form.isConnected){status.textContent='Opgeslagen';const summary=form.closest('details')?.querySelector('summary small');if(summary)summary.textContent=mode==='booking'?'Direct een afspraak boeken':'Eerst een aanvraag ontvangen';const code=document.getElementById('widget-code');if(code)code.value=widgetCode();}}}
   catch(error){if(form.isConnected){form.querySelector(`[name="intakeMode"][value="${previous.mode}"]`).checked=true;form.elements.serviceSelection.checked=previous.serviceSelection;document.getElementById('intake-service-option').hidden=previous.mode!=='request';document.getElementById('intake-preview').textContent=flowLabel(previous);status.textContent='Niet opgeslagen. Probeer opnieuw.';form.querySelector('.form-error').textContent=error.message;}}
   finally{controls.forEach(c=>c.disabled=false);}return;
  }
  if(el.dataset.question==='type'){el.closest('[data-question-id]').querySelector('[data-options-label]').hidden=el.value!=='select';return;}
  if(el.id==='lead-service'||el.id==='lead-date')return loadLeadSlots();
  if(el.id==='lead-time'){document.getElementById('lead-plan-submit').disabled=!el.value;return;}
  if(el.dataset.leadStage){el.disabled=true;const l=companyLeads().find(l=>l.id===el.dataset.leadStage);await request('lead/update',{tenant:t().id,id:l.id,revision:l.revision,stage:el.value});await refresh();}
  if(el.id==='calendar-day'){calendarDay=el.value||TODAY();return render();}
  if(el.id==='widget-mode'||el.id==='widget-show-button'){
   const form=el.form,show=document.getElementById('widget-show-button').checked,chosen=show?document.getElementById('widget-mode').value:'inline',previous=t().settings.widgetMode||'drawer',id=t().id,status=document.getElementById('widget-save-status');
   const controls=[...form.querySelectorAll('input,select')];controls.forEach(c=>c.disabled=true);status.textContent='Opslaan…';form.querySelector('.form-error').textContent='';
   const preview=mode=>{const button=mode!=='inline';document.getElementById('widget-show-button').checked=button;document.getElementById('widget-button-options').hidden=!button;if(button)document.getElementById('widget-mode').value=mode;document.getElementById('widget-display-summary').textContent=button?'Het formulier opent na een klik op de knop.':'Het formulier verschijnt direct op de pagina.';};
   preview(chosen);
   try{const saved=await request('tenant/save',{tenant:id,revision:t().revision,settings:{widgetMode:chosen}});if(t()?.id===id){workspace.tenant.settings.widgetMode=chosen;workspace.tenant.revision=saved.revision||workspace.tenant.revision+1;if(form.isConnected){status.textContent='Opgeslagen';document.getElementById('widget-code').value=widgetCode(chosen);form.closest('details').querySelector('summary small').textContent=chosen==='inline'?'Formulier direct op je website':'Openen via een knop';}}}
   catch(error){if(form.isConnected){preview(previous);status.textContent='Niet opgeslagen. Probeer opnieuw.';form.querySelector('.form-error').textContent=error.message;}}
   finally{controls.forEach(c=>c.disabled=false);}return;
  }
  if(el.dataset.bookingStage){el.disabled=true;await request('booking/update',{tenant:t().id,id:el.dataset.bookingStage,stage:el.value});await refresh();}
  if(el.dataset.contactStatus){el.disabled=true;await request('contact/update',{id:el.dataset.contactStatus,status:el.value});await refresh();}
 }catch(error){el.disabled=false;if(el.dataset.leadStage)el.value=companyLeads().find(l=>l.id===el.dataset.leadStage)?.stage||'new';if(el.dataset.bookingStage)el.value=workspace.bookings.find(b=>b.id===el.dataset.bookingStage)?.stage||'new';if(el.dataset.contactStatus)el.value=contacts.find(c=>c.id===el.dataset.contactStatus)?.status||'new';handleError(error);}
});
document.addEventListener('input',event=>{if(event.target.form?.id!=='brand-form')return;const values=Object.fromEntries(new FormData(event.target.form));const preview=document.getElementById('brand-preview');for(const [key,value] of Object.entries(brandVariables(values)))preview.style.setProperty(key,value);});
document.addEventListener('submit',event=>{
 if(!user)return;const form=event.target;if(!form.id||form.id==='login-form')return;event.preventDefault();
 submit(form,async f=>{
  if(form.id==='booking-move-form'){await request('booking/reschedule',{tenant:t().id,id:form.dataset.id,expected_date:form.dataset.date,expected_time:form.dataset.time,date:f.date,time:f.time});await refresh();closeModal();return toast('Afspraak verplaatst. Breng je klant op de hoogte.');}
  if(form.id==='manual-lead-form'){await request('lead/create',{...f,tenant:t().id,request_key:form.dataset.key});await refresh();closeModal();return toast('Lead toegevoegd.');}
  if(form.id==='crm-columns-form'){const columns=[...form.querySelectorAll('[data-column-id]')].map(el=>({id:el.dataset.columnId,name:el.value.trim()}));await request('crm/columns',{tenant:t().id,revision:Number(form.dataset.revision),columns});await refresh();closeModal();return toast('Kolommen opgeslagen.');}
  if(form.id==='form-fields-form'){await saveSettings({formFields:fieldsFromForm(form,!!t().settings.features.crmPlus)});document.getElementById('form-fields-form')?.closest('details')?.setAttribute('open','');return toast('Formuliervelden opgeslagen.');}
  if(form.id==='widget-form')return;
  if(form.id==='intake-form'){await saveSettings({intake:{mode:f.intakeMode,serviceSelection:!!f.serviceSelection}});return toast('Je werkwijze is opgeslagen.');}
  if(form.id==='lead-form'){await request('lead/update',{tenant:t().id,id:form.dataset.id,revision:Number(form.dataset.revision),stage:f.stage,internalNotes:f.internalNotes});await refresh();closeModal();return toast('Opvolging opgeslagen.');}
  if(form.id==='lead-plan-form'){
   try{await request('lead/schedule',{tenant:t().id,id:form.dataset.id,revision:Number(form.dataset.revision),service:f.service,date:f.date,time:f.time});await refresh();closeModal();return toast('Afspraak ingepland. Breng je klant op de hoogte.');}
   catch(e){if(e.status===409)await loadLeadSlots();throw e;}
  }
  if(form.id==='subscription-form'){await request('trial/upgrade',{...f,confirmed:!!f.confirmed});await refresh();return toast('Je activatieverzoek is ontvangen.');}
  if(form.id==='trial-convert-form'){await request('trial/convert',{tenant:form.dataset.id,confirmed:!!f.confirmed});await refresh();closeModal();return toast('Abonnement geactiveerd.');}
  if(form.id==='tenant-form'){
   const amount=Math.round(Number(f.amount)*100),r=await request('tenants/create',{name:f.name,admin_name:f.admin_name,email:f.email,sector:f.sector,plan_type:f.plan_type,monthly_cents:['monthly','annual'].includes(f.plan_type)?amount:0,lifetime_cents:f.plan_type==='lifetime'?amount:0,settings:{branding:{primary:f.primary,secondary:f.secondary,background:f.background,font:f.font}}});
   await refresh();inviteDialog(r.invite_url,r.mail);return;
  }
  if(form.id==='tenant-admin-form'){await request('tenant/admin',{tenant:form.dataset.id,revision:Number(form.dataset.revision),active:!!f.active,crm_plus:!!f.crmPlus,plan_type:f.plan_type,monthly_cents:Math.round(Number(f.monthlyAmount)*100),lifetime_cents:Math.round(Number(f.lifetimeAmount)*100),billing:{email:f.billingEmail,legalName:f.legalName,vatNumber:f.vatNumber,address:f.address,invoiceReference:f.invoiceReference,notes:f.notes}});await refresh();closeModal();return toast('Administratie opgeslagen.');}
  if(form.id==='service-form'){const image=await form.uploadImage(t().id);delete f.imageFile;await request('service/save',{...f,image,tenant:t().id,id:form.dataset.id,revision:Number(form.dataset.revision),duration:Number(f.duration),buffer:Number(f.buffer),price:Number(f.price),active:!!f.active});await refresh();closeModal();return toast('Dienst opgeslagen.');}
  if(form.id==='hours-form'){await saveSettings({hours:Array.from({length:7},(_,i)=>({open:!!f['open_'+i],start:f['start_'+i],end:f['end_'+i]})),notice:Number(f.notice),location:f.location});return toast('Beschikbaarheid opgeslagen.');}
  if(form.id==='block-form'){await saveSettings({blocks:[...new Set([...t().settings.blocks,f.date])]});return toast('Dag geblokkeerd.');}
  if(form.id==='brand-form'){await saveSettings({branding:f});return toast('Huisstijl opgeslagen.');}
  if(form.id==='modules-form'&&agency()){await saveSettings({features:Object.fromEntries(Object.keys(moduleLabels).map(k=>[k,!!f[k]]))});return toast('Modules opgeslagen.');}
  if(form.id==='email-form'){await saveSettings({subject:f.subject,message:f.message});return toast('E-mailtekst opgeslagen.');}
  if(form.id==='cancel-form'){await request('booking/update',{tenant:t().id,id:form.dataset.id,status:'cancelled'});await refresh();closeModal();return toast('Afspraak geannuleerd.');}
  if(form.id==='password-form'){if(f.password!==f.repeat_password)throw new Error('De nieuwe wachtwoorden komen niet overeen.');await request('password',f);user=null;workspace=null;setCsrf('');return renderLogin(signedIn,'Je wachtwoord is gewijzigd. Meld je opnieuw aan.');}
 });
});
async function start(){
 if(new URLSearchParams(location.search).get('mode')==='book'){const {startBooking}=await import('./booking.js?v=0.20.0');return startBooking();}
 try{const session=await request('me');setCsrf(session.csrf);await signedIn(session.user);}
 catch(error){renderLogin(signedIn,error.status===401?'':'Je omgeving wordt klaargezet of is tijdelijk niet bereikbaar. Aanmelden werkt zodra de verbinding actief is.');}
}
start();

// Native card dragging; selectors remain available for touch and keyboard users.
function clearDrag(){document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target'));dragCard=null;}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&crmFocus&&!document.getElementById('modal')?.open){crmFocus=false;render();document.querySelector('[data-action="crm-focus"]')?.focus();}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-card-id]');if(!card)return;if(movePending||e.target.closest('select,button,a')){e.preventDefault();return;}dragCard={id:card.dataset.cardId,type:card.dataset.cardType,stage:card.closest('[data-column]').dataset.column};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragCard.id);card.classList.add('dragging');});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-column]');if(!dragCard||!col||movePending)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(el=>{if(el!==col)el.classList.remove('drop-target');});col.classList.add('drop-target');});
document.addEventListener('dragend',clearDrag);
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-column]');if(!dragCard||!col)return;e.preventDefault();const card=dragCard,stage=col.dataset.column;clearDrag();if(stage===card.stage||movePending)return;movePending=true;const board=document.querySelector('.kanban');board?.setAttribute('aria-busy','true');try{const lead=companyLeads().find(l=>l.id===card.id);await request(card.type==='lead'?'lead/update':'booking/update',{tenant:t().id,id:card.id,stage,...(card.type==='lead'?{revision:lead.revision}:{})});await refresh();const moved=document.querySelector(`[data-card-id="${card.id}"]`);moved?.classList.add('just-moved');toast('Kaartje verplaatst.');}catch(error){handleError(error);}finally{movePending=false;board?.removeAttribute('aria-busy');}});
